/* Physical input mapping for Stats TV controls. Display owns screen rotation. */
(function(){
  const runtime=window.StatsSettings,$=id=>document.getElementById(id),esc=runtime.esc;
  const DEFAULT_KEYS={previous:"ArrowLeft",next:"ArrowRight",pair:"ArrowUp",sort_prev:"MouseWheelUp",sort_next:"MouseWheelDown"};
  const ACTIONS=[["previous","Previous Screen"],["next","Next Screen"],["pair","Next Team Matchup"],["sort_prev","Previous Measuring Stat"],["sort_next","Next Measuring Stat"]];
  const INPUTS=[["Keyboard",[["ArrowLeft","Arrow Left"],["ArrowRight","Arrow Right"],["ArrowUp","Arrow Up"],["ArrowDown","Arrow Down"],...Array.from({length:26},(_,i)=>[String.fromCharCode(97+i),String.fromCharCode(65+i)]),...Array.from({length:10},(_,i)=>[String(i),String(i)]),["PageUp","Page Up"],["PageDown","Page Down"],["Home","Home"],["End","End"],["Enter","Enter"],[" ","Space"],["[","["],["]","]"]]],["Mouse",[["MouseWheelUp","Mouse Wheel Up"],["MouseWheelDown","Mouse Wheel Down"],["MouseLeft","Mouse Left Click"],["MouseRight","Mouse Right Click"],["MouseMiddle","Mouse Middle Click"]]]];
  const allowed=new Set(INPUTS.flatMap(([,items])=>items.map(([value])=>value)));
  const options=()=>INPUTS.map(([label,items])=>`<optgroup label="${esc(label)}">${items.map(([value,name])=>`<option value="${esc(value)}">${esc(name)}</option>`).join("")}</optgroup>`).join("");
  function mount(){const host=$("settingsMapKeysControls");if(!host||$("mapKeysCard"))return;host.innerHTML=`<div class="card" id="mapKeysCard"><h2>Map Keys</h2><p class="small">Map keyboard or mouse inputs to TV actions. Screen rotation is configured in Display.</p><div class="grid">${ACTIONS.map(([key,label])=>`<div><label for="mapKey_${key}">${esc(label)}</label><select id="mapKey_${key}">${options()}</select></div>`).join("")}</div><div class="row" style="margin-top:12px"><button id="saveMapKeys" class="btn primary" type="button">Save Map Keys</button></div><div id="mapKeysStatus" class="small settings-status"></div></div>`;$("saveMapKeys").addEventListener("click",save);load();}
  async function load(){const status=$("mapKeysStatus");try{const data=await runtime.api("/api/config");const saved=data.settings?.keyboard_cycle_keys||{};ACTIONS.forEach(([key])=>{$(`mapKey_${key}`).value=allowed.has(saved[key])?saved[key]:DEFAULT_KEYS[key];});status.textContent="";}catch(error){status.textContent=error.message;}}
  async function save(){const button=$("saveMapKeys"),status=$("mapKeysStatus"),keys={};ACTIONS.forEach(([key])=>keys[key]=$(`mapKey_${key}`).value);if(new Set(Object.values(keys)).size!==ACTIONS.length){status.textContent="Each TV action needs a different input.";return;}button.disabled=true;status.textContent="Saving…";try{const data=await runtime.api("/api/keyboard-controls",runtime.json("POST",{keys}));const saved=data.keyboard?.keys||keys;ACTIONS.forEach(([key])=>$(`mapKey_${key}`).value=saved[key]||DEFAULT_KEYS[key]);status.textContent="Saved.";}catch(error){status.textContent=error.message;}finally{button.disabled=false;}}
  function start(){mount();}if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",start,{once:true});else start();
})();
